import React, { useState } from 'react';
import { Calendar, HardHat, Hash, FileWarning, ArrowRight, Download, Activity, Map } from 'lucide-react';

const CollectionSchedule = () => {
  const [selectedDate, setSelectedDate] = useState('2026-03-22');
  const [isMonthly, setIsMonthly] = useState(false);

  const logs = [
    {
      id: 'OP_772', time: '09:15', zone: 'NORTH_SECTOR', area: 'Hillside Drive',
      areaCode: 'HSD-44', worker: 'RAVI_KUMAR', bins: ['BN-401', 'BN-405', 'BN-409'],
      hasReport: true, reportTxt: 'SENSOR_OFFLINE', status: 'LIVE'
    },
    {
      id: 'OP_801', time: '14:30', zone: 'CENTRAL_HUB', area: 'Main Square',
      areaCode: 'MSQ-01', worker: 'SITA_M', bins: ['BN-101', 'BN-102'],
      hasReport: false, status: 'COMPLETED'
    }
  ];

  return (
    <div className="w-full h-full p-2 flex flex-col gap-10 font-black italic tracking-tighter uppercase overflow-hidden">

      {/* 🛠️ TOP COMMAND DIAL */}
      <div className="flex flex-col lg:flex-row gap-6 items-stretch">

        {/* DATE INPUT AS A "HARDWARE SLAP" */}
        <div className="relative flex-grow group">
          <div className="absolute inset-0 bg-[#47510B] translate-x-3 translate-y-3 rounded-tr-[80px] rounded-bl-[80px]" />
          <div className="relative bg-[#FFB6A9] border-[8px] border-[#47510B] p-8 rounded-tr-[80px] rounded-bl-[80px] flex items-center justify-between">
            <div>
              <p className="text-[12px] text-[#47510B] mb-2 tracking-[0.4em]">_TEMPORAL_SELECT</p>
              <input 
                type="date" 
                value={selectedDate}
                onChange={(e) => {setSelectedDate(e.target.value); setIsMonthly(false);}}
                className="bg-[#FFF24D] border-[5px] border-[#47510B] px-6 py-2 text-3xl text-[#47510B] rounded-full shadow-[6px_6px_0_0_#47510B] outline-none cursor-crosshair"
              />
            </div>
            <div className="hidden md:block text-right">
              <h2 className="text-5xl text-[#47510B] leading-none">DAY_LOG</h2>
              <p className="text-[#AB1717] text-sm mt-2">LINK_ESTABLISHED // 2026</p>
            </div>
          </div>
        </div>

        {/* MONTHLY MANIFEST "STAMP" */}
        <button 
          onClick={() => setIsMonthly(!isMonthly)}
          className="relative w-full lg:w-72 group active:scale-95 transition-transform"
        >
          <div className="absolute inset-0 bg-[#47510B] translate-x-2 translate-y-2 rounded-full" />
          <div className={`relative h-full border-[8px] border-[#47510B] rounded-full flex flex-col items-center justify-center p-6 ${isMonthly ? 'bg-[#FFF24D]' : 'bg-[#A1AED1]'}`}>
            <Download size={40} className="text-[#47510B] mb-2" />
            <span className="text-xl leading-none">MONTHLY<br/>MANIFEST</span>
          </div>
        </button>
      </div>

      {/* 🌊 CONTENT SCROLL AREA */}
      <div className="flex-grow overflow-y-auto pr-6 custom-scrollbar pb-20">

        {!isMonthly ? (
          <div className="flex flex-col gap-16 pt-4">
            {logs.map((log) => (
              <div key={log.id} className="relative group">

                {/* THE "STAMP" ON THE BACKGROUND */}
                <div className="absolute -top-10 -left-4 text-8xl opacity-10 text-[#47510B] select-none pointer-events-none">
                  {log.id}
                </div>

                {/* THE PUNCH CARD */}
                <div className="relative bg-white border-[8px] border-[#47510B] rounded-[40px] shadow-[15px_15px_0_0_#A1AED1] group-hover:shadow-[20px_20px_0_0_#FFF24D] transition-all flex flex-col lg:flex-row overflow-hidden">

                  {/* LEFT: THE TIME STRIP (BLUE) */}
                  <div className="bg-[#A1AED1] border-r-[8px] border-[#47510B] p-10 flex flex-col items-center justify-center gap-4 lg:w-56">
                    <div className="w-16 h-16 rounded-full bg-[#47510B] flex items-center justify-center border-4 border-white">
                       <Activity className="text-[#FFF24D]" size={30} />
                    </div>
                    <div className="text-center">
                      <p className="text-4xl leading-none">{log.time}</p>
                      <p className="text-[10px] tracking-widest mt-2 opacity-60">START_TIMESTAMP</p>
                    </div>
                  </div>

                  {/* CENTER: THE DATA CORE */}
                  <div className="flex-grow p-10 relative">
                    {/* AREA TAG */}
                    <div className="flex items-center gap-3 mb-6">
                      <span className="bg-[#AB1717] text-white px-5 py-1 rounded-md text-xs">{log.zone}</span>
                      <span className="bg-[#47510B] text-[#FFF24D] px-5 py-1 rounded-md text-xs tracking-widest">{log.areaCode}</span>
                    </div>

                    <h3 className="text-6xl text-[#47510B] mb-8 leading-none italic uppercase">
                      {log.area}
                    </h3>

                    {/* TELEMETRY ROW */}
                    <div className="flex flex-wrap gap-4">
                      {/* WORKER UNIT */}
                      <div className="bg-[#FDFAD8] border-[4px] border-[#47510B] p-4 rounded-2xl flex items-center gap-4 shadow-[5px_5px_0_0_#47510B]">
                        <HardHat size={30} className="text-[#47510B]" />
                        <div>
                          <p className="text-[10px] opacity-40 leading-none mb-1">UNIT_OPERATOR</p>
                          <p className="text-xl">{log.worker}</p>
                        </div>
                      </div>

                      {/* BIN IDs SCANNER */}
                      <div className="flex-grow bg-[#47510B] p-4 rounded-2xl flex flex-col gap-2">
                         <p className="text-[10px] text-[#A1AED1] tracking-widest">ASSIGNED_TELEMETRY_NODES</p>
                         <div className="flex gap-2">
                           {log.bins.map(b => (
                             <span key={b} className="text-[10px] bg-white/10 px-3 py-1 rounded text-white font-mono">
                               {b}
                             </span>
                           ))}
                         </div>
                      </div>
                    </div>

                    {/* INCIDENT SLAP */}
                    {log.hasReport && (
                      <div className="absolute -top-4 right-10 bg-[#AB1717] text-white p-6 border-[5px] border-[#47510B] -rotate-6 shadow-xl animate-pulse">
                         <FileWarning size={32} />
                         <p className="text-[10px] mt-1 font-black underline">ERROR: {log.reportTxt}</p>
                      </div>
                    )}
                  </div>

                  {/* RIGHT: THE STATUS TAB */}
                  <div className="bg-[#FFF24D]/20 border-l-[8px] border-[#47510B] flex items-center justify-center lg:w-32 hover:bg-[#FFF24D] cursor-pointer group/btn">
                    <ArrowRight size={50} className="text-[#47510B] group-hover/btn:translate-x-4 transition-transform" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          /* 📦 THE MONTHLY ARCHIVE "DRAWER" */
          <div className="relative pt-10">
            <div className="absolute inset-0 bg-[#47510B] translate-x-4 translate-y-4 rounded-[60px]" />
            <div className="relative bg-[#A1AED1] border-[10px] border-[#47510B] p-20 rounded-[60px] flex flex-col items-center">
              <div className="w-40 h-40 bg-[#FFB6A9] border-[8px] border-[#47510B] rounded-full flex items-center justify-center shadow-[10px_10px_0_0_#FFF24D] mb-10">
                <Download size={80} className="text-[#47510B]" />
              </div>
              <h2 className="text-7xl text-[#47510B] leading-none mb-6">SYSTEM_MANIFEST</h2>
              <div className="flex gap-6">
                <button className="bg-[#47510B] text-[#FFF24D] px-12 py-5 rounded-full text-2xl border-4 border-white shadow-[8px_8px_0_0_#AB1717] hover:-translate-y-2 transition-transform uppercase">
                  Export_CSV
                </button>
                <button className="bg-white text-[#47510B] px-12 py-5 rounded-full text-2xl border-4 border-[#47510B] shadow-[8px_8px_0_0_#47510B] hover:-translate-y-2 transition-transform uppercase">
                  Sync_Archive
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* 🧭 FOOTER STATUS BAR */}
      <div className="fixed bottom-10 left-80 right-10 h-16 bg-[#47510B] rounded-full border-4 border-white shadow-[10px_10px_0_0_#A1AED1] flex items-center px-10 justify-between text-white text-xs">
         <div className="flex gap-8">
            <span className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-[#FFF24D]" /> SYSTEM_STATUS: NOMINAL</span>
            <span className="flex items-center gap-2 text-[#FFB6A9]"><div className="w-2 h-2 rounded-full bg-[#FFB6A9] animate-ping" /> REAL_TIME_SYNC_ACTIVE</span>
         </div>
         <span className="opacity-40 italic">TRASH_TRACK_OS // ADM_VER_2.6</span>
      </div>

    </div>
  );
};

export default CollectionSchedule;
